import { useEffect, useState } from "react";
import { useQuery, gql } from "@apollo/client";
import { User } from "../interfaces/user";

// this is a gql query that has Me as a query key to fetch the user.
const GET_ME = gql`
  query Me {
    me {
      id
      email
    }
  }
`;

const useGetMe = () => {
  const { data, loading, error } = useQuery<{ me: User }>(GET_ME, {
    fetchPolicy: "network-only", // Ensure fresh data is fetched
    context: {
      headers: {
        // Include any additional headers if needed
      },
      credentials: "include", // Important: Include credentials (cookies)
    },
  });

  return {
    user: data?.me,
    loading,
    error,
  };
};

export { useGetMe };
